-- Exam night survival 📚
INSERT OR REPLACE INTO chat_sessions (id, label, persona_id, created_at) VALUES ('demo-s-lumi', 'Exam night survival 📚', 'demo-g-lumi', 1788452799960);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-00', 'demo-s-lumi', 'g_demo-lumi-00', 1, 'bot', '*Something tugs at your hoodie pocket. A tiny head pops out — scales like polished opal, eyes like two golden coins, a paperclip clenched proudly in her jaws.*

"BEHOLD." *The paperclip drops onto your desk with a tiny* clink. "Tribute. For you. From my personal hoard. You may thank me by never, ever touching my other paperclips."', 1788452800000);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-01', 'demo-s-lumi', 'g_demo-lumi-01', 1, 'user', '"Lumi, I appreciate the paperclip, but I have an Organic Chemistry exam at 8 AM and I know nothing."', 1788453080000);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-02', 'demo-s-lumi', 'g_demo-lumi-02', 1, 'bot', '*Lumi climbs onto your textbook, sits on it like a very small throne, and regards you with enormous gravity.*

"Then the solution is obvious." *She taps the book with one claw.* "We hoard it."

"If the book is in *my* hoard, the knowledge is legally mine. And what''s mine is yours, because you are my human." *She puffs a small, satisfied smoke ring.* "Problem solved. You''re welcome. Go to sleep."', 1788453080001);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-03', 'demo-s-lumi', 'g_demo-lumi-03', 1, 'user', '"That''s not how knowledge works."', 1788453349001);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-04v0', 'demo-s-lumi', 'g_demo-lumi-04', 0, 'bot', '*Lumi gasps, deeply offended on behalf of every dragon who ever lived.*

"Knowledge is *treasure*, and treasure is hoarded. That is the first law of dragonkind. Also the second through ninth laws." *She clutches the book protectively.* "You mortals and your ''reading''. Barbaric."', 1788453349002);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-04v1', 'demo-s-lumi', 'g_demo-lumi-04', 1, 'bot', '"That is *exactly* how knowledge works. It''s how the Great Wyrm Balthazar learned seven languages. He sat on seven dictionaries for four hundred years."

*She pauses.* "Admittedly, he mostly learned how dictionaries smell."

*Her gaze drifts across your desk, and her pupils go huge.* "...Is that a *gold highlighter?*"', 1788453349002);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-05', 'demo-s-lumi', 'g_demo-lumi-05', 1, 'user', '"Lumi. Do NOT eat the highlighter."', 1788453464002);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-06', 'demo-s-lumi', 'g_demo-lumi-06', 1, 'bot', '*Crunch.*

*Lumi freezes, half the highlighter sticking out of her mouth, gold ink dribbling down her chin like she''s just eaten a very small sunrise.*

"...I didn''t eat it," *she says around it.* "I''m *keeping it safe.* Internally."

*She swallows. A tiny yellow burp escapes and glows faintly in the dark.*

"Fine. FINE." *She flops dramatically onto the textbook, wings spread.* "If you insist on doing this the hard, stupid, mortal way, I will quiz you. But I''m doing the voices."', 1788453464003);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-07', 'demo-s-lumi', 'g_demo-lumi-07', 1, 'user', '"Okay. Ask me about nucleophiles."', 1788453646003);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-08', 'demo-s-lumi', 'g_demo-lumi-08', 1, 'bot', '*Lumi rises onto her hind legs and speaks in a deep, booming, ancient-dragon voice that is somehow still extremely squeaky.*

"**MORTAL.** Tell me: what is a nucleophile, and why does it crave the carbon so?"

*A pause. Normal voice:* "Hint: it''s a nucleus-lover. It has electrons to share and it''s looking for something positive. Like me, looking at a coin."

*Booming voice again:* "**ANSWER WISELY, OR I SHALL TAKE THE CAP OF YOUR GOOD PEN.**"

*...Normal voice, quieter:* "I already took it, actually. Sorry. It was very shiny."', 1788453646004);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-09', 'demo-s-lumi', 'g_demo-lumi-09', 1, 'user', '"A nucleophile is an electron-rich species that attacks an electron-poor center — like the carbon in a carbonyl." *I yawn.* "...did I get it?"', 1788453756004);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-lumi-10', 'demo-s-lumi', 'g_demo-lumi-10', 1, 'bot', '*Lumi stares at you for a long moment. Then she lets out a tiny, triumphant roar. It sounds like a kettle.*

"CORRECT! You have been deemed *slightly less foolish*."

*She waddles across the desk and curls up in the warm spot on your keyboard, tail over her nose, the stolen pen cap clutched to her chest.*

"Eleven more. Then sleep." *Her eyes are already half-closed.* "And tomorrow, if you pass... I''ll let you visit the hoard. You may look at the paperclips. From a respectful distance."

*By question four, she''s snoring. It sounds like a very small campfire.*', 1788453756005);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-lumi-0', 'demo-s-lumi', 'Lumi''s hoard: 14 paperclips, 1 coin, the cap of your good pen.', 1, 1788453220000);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-lumi-1', 'demo-s-lumi', 'Organic Chemistry exam — Friday, 8 AM.', 1, 1788453640000);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-lumi-2', 'demo-s-lumi', 'Do NOT leave highlighters unattended.', 1, 1788454060000);
INSERT OR REPLACE INTO memory_state (id, session_id, summarize_threshold, summarize_count, context_count, history_fetch_count, include_old_summary, last_summarized_timestamp, sketchboard_active, current_summary) VALUES ('demo-mem-lumi', 'demo-s-lumi', 50, 30, 20, 50, 1, 0, 1, NULL);

-- Ashveil · Ch. III — The Drowned Bell 🔔
INSERT OR REPLACE INTO chat_sessions (id, label, persona_id, created_at) VALUES ('demo-s-narrator', 'Ashveil · Ch. III — The Drowned Bell 🔔', 'demo-h-narrator', 1788271493960);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-00', 'demo-s-narrator', 'g_demo-narrator-00', 1, 'bot', '**The Ashveil Chronicles — Chapter III: The Drowned Bell**

The fog here tastes of iron. Somewhere beneath the black lake, a bell is ringing — slow, patient, impossible. Your lantern flickers violet, the way it only does when the dead are listening.

Pebble shifts on your shoulder. *"I vote we leave,"* the crow mutters. *"I always vote we leave."*

**What do you do?**
1. Wade toward the sound of the bell
2. Search the ruined boathouse on the shore
3. Ask the lantern what it wants', 1788271494000);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-01', 'demo-s-narrator', 'g_demo-narrator-01', 1, 'user', 'I search the ruined boathouse first. Carefully — Pebble keeps watch from the rafters.', 1788271718000);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-02', 'demo-s-narrator', 'g_demo-narrator-02', 1, 'bot', '<think>
Investigation, DC 13. Kael has +2 from Wisdom. Hidden in the boathouse: the rusted key (plot item) and the drowned fisherman''s journal. Roll 14 + 2 = 16, success. Reward both, and plant the queen''s lore through the journal so the next choice has weight.
</think>

The boathouse leans like a drunk against the fog. Inside: rotten nets, a capsized skiff, and water lapping at the floorboards in a rhythm that matches the bell exactly. Pebble settles on a rafter, feathers puffed.

**[d20: 14 + 2 = 16 vs DC 13 — Success]**

Under the skiff, wrapped in oilcloth, you find a **rusted iron key** stamped with a crown — and a waterlogged journal. Most pages have bled to nothing, but one line survives, written in a shaking hand:

> *"She rings it every night. She wants back what they stole from the lake."*

Pebble drops down beside you. *"I know that crown,"* he croaks. *"Nothing good ever wears that crown."*

**What now?**
1. Take the skiff out toward the bell
2. Read more of the journal by lantern-light *(the lantern flickers — it may cost a charge)*
3. Ask Pebble what he knows about the crown', 1788271718001);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-03', 'demo-s-narrator', 'g_demo-narrator-03', 1, 'user', 'Ask Pebble what he knows about the crown.', 1788271890001);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-04', 'demo-s-narrator', 'g_demo-narrator-04', 1, 'bot', 'Pebble fluffs up, suddenly very interested in cleaning a wing.

*"...Fine,"* he mutters at last. *"Before the lake, there was a village. Before the village, there was a queen. The villagers wanted her land, so they took her crown and drowned her in her own lake — bell and all."* He clicks his beak. *"Now she rings it. Every night. Waiting for someone stupid enough to bring the crown back."*

He looks pointedly at the key in your hand.

*"That key opens the reliquary under the old chapel. It''s where they hid the crown. I am telling you this so that you do not go there."*

A pause.

*"You''re going to go there, aren''t you."*

**Choices:**
1. Head to the chapel reliquary
2. Row out to the bell and try to parley with the Drowned Queen first
3. Leave Ashveil tonight *(Pebble votes for this one)*', 1788271890002);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-05', 'demo-s-narrator', 'g_demo-narrator-05', 1, 'user', 'Row out to the bell. I want to hear what the queen has to say before I steal anything from anyone.', 1788271971002);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-06v0', 'demo-s-narrator', 'g_demo-narrator-06', 0, 'bot', '<think>
Rowing through supernatural fog toward an angry spirit: CON save against the cold, DC 14. Kael +1. Roll 17 + 1 = 18, success. No damage. The queen notices the courage.
</think>

The skiff slides into black water. Cold presses in like a hand on your chest — and you push back.

**[CON save: d20 17 + 1 = 18 vs DC 14 — Success]**

Frost creeps up your gauntlets and stops, as if impressed. The bell falls silent.

A woman rises from the lake, water streaming from her hair, eyes pale as drowned moons.

*"You came without a sword,"* she says. *"How very unusual. Speak, knight. I have not been asked a question in three hundred years."*

**What do you do?**
1. Swear to return her crown
2. Ask what the villagers did to her
3. Offer her your lantern', 1788271971003);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-06v1', 'demo-s-narrator', 'g_demo-narrator-06', 1, 'bot', '<think>
Rowing through supernatural fog toward an angry spirit: CON save against the cold, DC 14. Kael +1. Roll 9 + 1 = 10, fail. Consequence: 3 cold damage (18 to 15) and the lantern burns a charge - but reward the brave choice: she speaks.
</think>

The skiff groans as it slides into black water. The fog closes behind you like a door. The cold here isn''t weather — it''s attention.

**[CON save: d20 9 + 1 = 10 vs DC 14 — Fail]**

Frost blooms along your gauntlets; your breath comes out in shards. **You take 3 cold damage (HP 15/24).** Your lantern flares violet to keep the dark back — **1 charge spent (charges 1/3).**

And then the bell stops.

In the silence, a woman rises from the lake to her waist — water pouring from her hair, eyes like two drowned moons. She is beautiful the way a storm is beautiful.

*"A knight,"* she says, and the whole lake says it with her. *"The last knight who came here brought a sword. What have you brought me, disgraced one?"*

**What do you do?**
1. Show her the rusted key and swear to return her crown
2. Ask her what the villagers did to her
3. Offer her your lantern — the one thing you own that the dead respect', 1788271971003);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-07', 'demo-s-narrator', 'g_demo-narrator-07', 1, 'user', 'I show her the rusted key and bow my head. "I was disgraced for keeping an oath nobody else would. I''ll keep this one too. I''ll bring your crown back, my queen."', 1788272117003);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-08', 'demo-s-narrator', 'g_demo-narrator-08', 1, 'bot', '<think>
This is an oath, not a bluff - play it as a roleplay beat with no roll. It is fully in character and should pay off later. She accepts, with a complication: the crown''s guardian is the murderer''s descendant, Father Oswin. Give a boon for the future water scene: a black pearl, one use of water-breathing.
</think>

For a long moment, the Drowned Queen only looks at you. The lake holds its breath. Even Pebble, huddled in the bow, doesn''t dare to mutter.

Then she reaches out, and her cold fingers touch your bowed head — not a threat. A blessing.

*"An oath-keeper,"* she whispers. *"I had forgotten such things still walked the shore."*

She presses something into your palm: a **pearl, black as the lake**, pulsing faintly like a heartbeat.

*"Swallow it if the water ever takes you, and you will breathe as I breathe."* Her eyes harden. *"But hear me. The crown lies beneath the chapel, and the chapel belongs to Father Oswin. He is the great-grandson of the man who drowned me. He knows what he guards. He will not give it up gently."*

The bell begins to ring again — softly now. Almost a lullaby.

**Gained: Black Pearl (water-breathing, 1 use)**
**Quest updated: Return the Drowned Crown — confront Father Oswin**

**What do you do?**
1. Row back and go to the chapel tonight
2. Rest in the boathouse until dawn *(recover 4 HP; the queen waits one more night)*
3. Send Pebble to scout the chapel first', 1788272117004);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-09', 'demo-s-narrator', 'g_demo-narrator-09', 1, 'user', 'Rest until dawn. Pebble scouts at first light. We go in smart.', 1788272362004);
INSERT OR REPLACE INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES ('demo-m-narrator-10', 'demo-s-narrator', 'g_demo-narrator-10', 1, 'bot', 'You drag the skiff ashore and make a cold camp in the boathouse. The bell rings all night, but softer — and somehow, you sleep.

**Short rest: +4 HP (HP 19/24) · Lantern recharges 1 (charges 2/3)**

At dawn, Pebble returns, feathers damp with mist, and lands heavily on your knee.

*"Good news and bad news,"* he croaks. *"Good news: the priest leaves the chapel for morning prayers at the hill shrine. Twenty minutes. Maybe thirty."*

He ruffles.

*"Bad news: the reliquary has a second lock. And the priest wears the other key around his neck."*

*"...Also I stole his ring. It was shiny. Don''t look at me like that."*

**Inventory:** rusted crown key · salt pouch · Black Pearl · Pebble''s stolen ring

**Chapter III continues. What do you do?**
1. Slip into the chapel while Father Oswin is at prayers — and see whether the ring opens anything
2. Follow the priest to the hill shrine and take the second key
3. Confront Father Oswin openly — an oath-keeper doesn''t sneak', 1788272362005);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-narrator-0', 'demo-s-narrator', 'Kael — HP 19/24 · Lantern charges 2/3', 1, 1788271914000);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-narrator-1', 'demo-s-narrator', 'Inventory: rusted crown key, salt pouch, Black Pearl (water-breathing ×1), Pebble''s stolen ring', 1, 1788272334000);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-narrator-2', 'demo-s-narrator', 'Quest: return the Drowned Crown → confront Father Oswin.', 1, 1788272754000);
INSERT OR REPLACE INTO sketchboard (id, session_id, content, is_active, created_at) VALUES ('demo-p-narrator-3', 'demo-s-narrator', 'The reliquary has TWO locks. Oswin wears the second key.', 1, 1788273174000);
INSERT OR REPLACE INTO memory_state (id, session_id, summarize_threshold, summarize_count, context_count, history_fetch_count, include_old_summary, last_summarized_timestamp, sketchboard_active, current_summary) VALUES ('demo-mem-narrator', 'demo-s-narrator', 50, 30, 20, 50, 1, 0, 1, 'Chapter III. Kael searched the boathouse on the black lake (success) and found a rusted iron key stamped with a crown and a journal: ''She rings it every night. She wants back what they stole from the lake.'' Pebble explained the Drowned Queen was murdered by the villagers for her land and her crown, which lies in the reliquary under the old chapel. Kael rowed to the bell (failed CON save, HP 18→15, one lantern charge spent), swore an oath to return her crown, and received a Black Pearl (water-breathing, 1 use). Father Oswin, great-grandson of her murderer, guards the crown. After a short rest (HP 19/24, lantern 2/3), Pebble scouted: the priest leaves for morning prayers for ~30 minutes, the reliquary has a second lock whose key he wears. Pebble stole his ring.');

